  JARR_PRON("عَنْهُمْ", "an", "عَنْ", "هُمْ", " («onlardan»)", note_ar=" — وَالْجَارُّ وَالْمَجْرُورُ مُتَعَلِّقَانِ بِـ«تَنْجَلِي»", note_en=" — the phrase hangs on «clear away»", note_tr=" — câr-mecrûr «kalkar»a müteallik"),
  FAIL("غَيَايَاتُ", "ghayaya", extra=["jam-muannath-salim"], note_ar="، مُضَافٌ — جَمْعُ غَيَايَةٍ: كُلُّ مَا أَظَلَّ الْإِنْسَانَ", note_en=", annexed — the plural of غَيَايَة, whatever casts a shade over a man", note_tr=", muzâf — gayâye'nin çoğulu: insanı gölgeleyen her şey"),
